// current context. A queued pull is not running.
func (m Model) pullRunning(name string) bool { return m.runningOn(name, jobs.KindPull) }

func (m Model) runningOn(name string, kind jobs.Kind) bool {
	for _, a := range jobs.ActiveOn(m.jobs, m.contextName, name, kind) {
		if a.Item.State == jobs.ItemRunning {
			return true
		}
	}
	return false
}

// ActivityTables returns the read-only face of the view's table, keyed by the
// name the activity-column guard (internal/app) knows it by. Tests only.
func (m Model) ActivityTables() map[string]datatable.ActivityTable {
	return map[string]datatable.ActivityTable{"oci/images": &m.imageTable}
}
	}
	return m, nil
}

// handleFrameMsg takes the blink phase of the activity column. Nothing is
// rebuilt: the table reads the phase at render. The footer frame is the
// router's only while no tab load is running: the view's own spinner owns it
// then, and two writers would fight every frame.
func (m Model) handleFrameMsg(msg jobs.FrameMsg) (tea.Model, tea.Cmd) {
	m.imageTable.SetBlinkPhase(msg.Blink)
	if !m.loading && !m.loadingNets && !m.loadingVols && !m.loadingRegs {
		m.footer.SetSpinnerFrame(msg.RenderedFrame)
	}
	return m, nil
}

// WantsBlink reports whether an Images row is in an animated state (running,
// or an action observed on it). A queued row and a remembered failure are
// steady. It is the level the router's BlinkingView check reads.
func (m Model) WantsBlink() bool {
	for _, r := range m.imageTable.Items() {
	return fmt.Sprintf("%d", count)
}

// updateImageTable rebuilds the image table rows.
//
// Every caller reaches here after changing something the row shows — a scan
// started, finished, or the list came back — so the decoration is recomputed
// wholesale rather than patched in place.
func (m *Model) updateImageTable() {
	m.imageTable.SetItems(m.imageRows())
	m.imageTable.SetHeight(m.tableHeight())
}

// networkColumnID and volumeColumnDriver are where a running action puts its
// spinner — the cell each table can spare while one row is being removed.
const (
	networkColumnID    = 0
	volumeColumnDriver = 1
)

// networkColumns describes the Networks tab. Neither this table nor the volumes
// one sorts or filters today, so no Less and no Search: `/` and `.` stay inert
// rather than being wired to a bar this view's footer does not render.
func networkColumns() []datatable.Column[docker.Network] {
	return []datatable.Column[docker.Network]{
		{Title: "ID", Sizing: datatable.SizingFixed, MinWidth: 14, Cell: func(n docker.Network) string { return shortID(n.ID) }},
		{Title: "Name", Sizing: datatable.SizingContent, MinWidth: 20, Flex: 1, Cell: func(n docker.Network) string { return n.Name }},
		{Title: "Driver", Sizing: datatable.SizingFixed, Optional: true, MinWidth: 12, Cell: func(n docker.Network) string { return n.Driver }},
		{Title: "Scope", Sizing: datatable.SizingFixed, Optional: true, MinWidth: 10, Cell: func(n docker.Network) string { return n.Scope }},
	}
}

// volumeColumns describes the Volumes tab.
func volumeColumns() []datatable.Column[docker.Volume] {
	return []datatable.Column[docker.Volume]{
		{Title: "Name", Sizing: datatable.SizingContent, MinWidth: 20, Cell: func(v docker.Volume) string { return v.Name }},
		{Title: "Driver", Sizing: datatable.SizingFixed, MinWidth: 12, Cell: func(v docker.Volume) string { return v.Driver }},
		{Title: "Mountpoint", Sizing: datatable.SizingContent, Optional: true, TruncateHead: true, MinWidth: 20, Flex: 1, Cell: func(v docker.Volume) string { return v.Mountpoint }},
	}
}

// shortID truncates a Docker ID to the twelve characters the CLI shows.
func shortID(id string) string {
	if len(id) > 12 {
		return id[:12]
	}
	return id
}

// registryRow is one line of the Registries tab.
//
// The tab shows two populations in one table — the configured entries at the
// top level, and one group's discovered members after `→` — and datatable is
// generic over a single T, so the row type has to carry both. explorerRow
// exists for the same reason.
//
// config is the index into Model.registries the row stands for, and -1 for a
// discovered member: a member is not a config entry, has no alias of its own to
// edit and no credentials but its group's, so every action on the tab has to be
// able to tell the two apart. Carrying it on the row is also what lets the
// cursor be resolved without indexing m.registries by row number, which is
// correct today only because this table neither sorts nor filters.
type registryRow struct {
	alias   string
	url     string
	kind    string
	auth    string
	logged  string
	members string
	config  int
}

// registryColumnLogged is the cell a login or logout replaces with its spinner:
// it is precisely the answer the operation is about to change.
const registryColumnLogged = 4

// registryColumns describes the Registries tab. Nothing sorts or searches: the
// list is the order the config declares, which is the order the user wrote.
func registryColumns() []datatable.Column[registryRow] {
	return []datatable.Column[registryRow]{
		{Title: "Alias", Sizing: datatable.SizingContent, MinWidth: 16, Cell: func(r registryRow) string { return r.alias }},
		{Title: "URL", Sizing: datatable.SizingContent, TruncateHead: true, MinWidth: 20, Flex: 1, Cell: func(r registryRow) string { return r.url }},
		{Title: "Kind", Sizing: datatable.SizingFixed, Optional: true, MinWidth: 10, Cell: func(r registryRow) string { return r.kind }},
		{Title: "Auth", Sizing: datatable.SizingFixed, Optional: true, MinWidth: 12, Cell: func(r registryRow) string { return r.auth }}, // holds "credentials"
		{Title: "Logged", Sizing: datatable.SizingFixed, MinWidth: 8, Cell: func(r registryRow) string { return r.logged }},
		{Title: "Members", Sizing: datatable.SizingFixed, Optional: true, MinWidth: 16, Cell: func(r registryRow) string { return r.members }}, // holds "12 · 30 days ago"
	}
}

// registryRef is what an entry is displayed as: its address, not its URL.
//
// The prefix has to be on screen or the tab says nothing useful — one line per
// proxy is one host repeated, and a group's members all answer to the same host
// too (§3.18). Joined with a slash because that is exactly the head of the pull
// reference: `docker pull nexus.example.com/dhi-io-proxy/eclipse-temurin:21`.
// Plain text only — Rule 122.
func registryRef(url, repoPrefix string) string {
	if repoPrefix == "" {
		return url
	}
	return strings.TrimSuffix(url, "/") + "/" + repoPrefix
}

// membersCell reports what the last discovery for a group found, and when.
//
// The "when" is not decoration: a cache with no visible age is worse than the
		// A pulling placeholder row carries no Image yet, so its ID is empty —
		// falling back to the name keeps two concurrent pulls from colliding
		// on the same key.
		Key: func(r imageRow) string {
			if r.Image.ID == "" {
				return "pull:" + r.RawName
			}
			return r.Image.ID
		},
		// No StatusColumn: the activity column shows a removal in flight, and a
		// spinner on another cell would animate it twice.
	})

	nt := datatable.New(datatable.Config[docker.Network]{
		Columns:      networkColumns(),
		SortColumn:   -1,
		Key:          func(n docker.Network) string { return n.ID },
		StatusColumn: networkColumnID,
	})
	nt.Blur()

	vt := datatable.New(datatable.Config[docker.Volume]{
		Columns:    volumeColumns(),
		SortColumn: -1,
		// A volume has no ID: its name is its identity, which is also why the
		// spinner cannot go there — it is the one cell that says which row this
		// is. Driver is the expendable one, and it reads "local" on very nearly
		// every volume there has ever been.
		Key:          func(v docker.Volume) string { return v.Name },
		StatusColumn: volumeColumnDriver,
	})
	vt.Blur()

	rt := datatable.New(datatable.Config[registryRow]{
		Columns:    registryColumns(),
		SortColumn: -1,
		// The URL, because that is what docker keys a login on and what
		// RegistryLoginCompleteMsg carries back. Two entries declared on one
		// host therefore spin together — which is right: one `docker login`
		// really does change the answer for both. This is the one place D40's
		// rule does not apply, and it does not apply because the *operation* is
		// host-scoped, not because the identity is convenient.
		Key: func(r registryRow) string { return r.url },
		// Logged is the cell a login is about to change, so it is the one to
		// spend while it runs.
		StatusColumn: registryColumnLogged,
	})
	rt.Blur()

	return Model{
		config:              cfg,
		activeTab:           tabImages,
		scanCache:           make(map[string]cache.ImageScanEntry),
		signatures:          make(map[string]trust.Result),
		sigAsked:            make(map[string]sigAsk),
		sigVerifying:        make(map[string]bool),
